package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public final class Beta996UiNativeTest extends Instrumentation {
 int checks;Throwable fail;void check(boolean v,String label){checks++;if(!v)throw new AssertionError(label);}void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable t){fail=t;}});if(fail!=null)throw new AssertionError(fail);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 void bounds(View v){if(v==null||v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getLayout()!=null&&t.length()>0){android.text.Layout l=t.getLayout();check(l.getEllipsisCount(l.getLineCount()-1)==0,"No body ellipsis: "+t.getText());check(t.getHeight()>=t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()+l.getLineBottom(l.getLineCount()-1),"No body clipping: "+t.getText());}if(v instanceof Button)check(v.getHeight()>=48*v.getResources().getDisplayMetrics().density,"48dp button");}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)bounds(((ViewGroup)v).getChildAt(i));}
 static String text(View v){if(v instanceof TextView)return ((TextView)v).getText().toString();StringBuilder s=new StringBuilder();if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(text(((ViewGroup)v).getChildAt(i)));return s.toString();}
 @Override public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();String originalName=BetaIdentity.prefs(c).getString("name","");try{check(Build.MODEL.contains("sdk")&&c.getPackageName().equals("dev.bennett.codexmeter.trial")&&TrialDemo.active(c),"Owned fake beta");check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName.equals("9.9.6"),"Final 9.9.6");String account=SubscriptionStore.accountKey(c);JSONObject initial=BetaGrowthStore.load(c,account);long total=initial.getLong("total");String equipped=initial.optString("equipped");
 MainActivity home=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1600);waitForIdleSync();Thread.sleep(400);main(()->{View root=home.findViewById(android.R.id.content);TextView name=(TextView)root.findViewWithTag("beta996:name"),title=(TextView)root.findViewWithTag("beta996:title");check(name!=null&&name.isShown()&&name.getWidth()>0&&name.getHeight()>0,"Actual home name has visible bounds: "+(name==null?"absent":name.getWidth()+"x"+name.getHeight()));check(title!=null&&title.isShown()&&title.getWidth()>0&&title.getHeight()>0,"Actual title has visible bounds");check(root.findViewWithTag("beta996:tier-badge")!=null,"Actual crest");bounds(root.findViewWithTag("beta996:identity"));bounds(home.findViewById(R.id.matte_bottom));});capture(c,"home");
 BetaIdentity.save(c,"긴이름한글 EnglishUser123456");BetaCatalogActivity editor=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).putExtra("titles",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(400);main(editor::finish);Thread.sleep(700);waitForIdleSync();main(()->check(text(home.findViewById(android.R.id.content).findViewWithTag("beta996:name")).equals(BetaIdentity.name(c)),"Home updates name on return without restart"));
 check(BetaGrowthStore.equip(c,account,"rpg3.starter"),"Explicit alternate title");BetaCatalogActivity away=(BetaCatalogActivity)startActivitySync(new Intent(c,BetaCatalogActivity.class).putExtra("titles",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(300);main(away::finish);Thread.sleep(650);waitForIdleSync();main(()->check(text(home.findViewById(android.R.id.content).findViewWithTag("beta996:title")).equals(BetaIdentity.title(c,"rpg3.starter")),"Home updates title from new display cache"));main(home::finish);BetaGrowthStore.equip(c,account,equipped);BetaIdentity.save(c,originalName);
 for(Class<?> cls:new Class<?>[]{GrowthActivity.class,BetaCatalogActivity.class,MeterSettingsActivity.class}){Activity a=startActivitySync(new Intent(c,cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(650);waitForIdleSync();main(()->bounds(a.findViewById(R.id.dashboard_content)));if(a instanceof BetaCatalogActivity)capture(c,"catalog");main(a::finish);}
 check(BetaGrowthStore.load(c,account).getLong("total")==total,"Render/name/equipment/catalog/settings give no XP");result.putString("stream","Beta9.9.6 adaptive UI: "+checks+" checks passed; actual home bounds/name-title refresh/touch/text, synthetic only.\n");finish(-1,result);
 }catch(Throwable t){BetaIdentity.save(c,originalName);result.putString("stream",android.util.Log.getStackTraceString(t));finish(0,result);}}
 void capture(Context c,String label)throws Exception{waitForIdleSync();java.io.File folder=new java.io.File(c.getExternalFilesDir(null),"beta996-ui-captures");folder.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(folder,label+".png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
}
